import {TYPES,selectQuestions,detectChapters,matches,grade,safeLoad} from './core.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={hex:'<path d="m12 2 8.7 5v10L12 22l-8.7-5V7Z"/><path d="m7 8 5-3 5 3v8l-5 3-5-3Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',review:'<path d="M6 3h12v19l-6-4-6 4Z"/><path d="M9 8h6m-6 4h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4 10-10"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',leaf:'<path d="M20 3C3 1 0 16 11 19 22 22 22 10 20 3Z"/><path d="m4 22 12-14"/>',file:'<path d="M5 2h9l5 5v15H5Z"/><path d="M14 2v6h5M8 13h8m-8 4h6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
function icon(n,size=17){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.hex}</svg>`}
let chapters,bank,examples,view='home',selected=19,group='all',query='',count=8,types=[...TYPES],recall=false,source=null,uploading=false,uploadMessage='',quiz=null,bookURL=null,bookName='',draftSelection=null,processingBook=false;
let progress=safeLoad(localStorage,'or-progress-v1',{history:[],wrong:[],seen:[],correct:0,answered:0});
if(!Array.isArray(progress.history)||!Array.isArray(progress.wrong)||!Array.isArray(progress.seen)||!Number.isFinite(progress.correct)||!Number.isFinite(progress.answered))progress={history:[],wrong:[],seen:[],correct:0,answered:0};
let storageFailed=false;
function save(){try{localStorage.setItem('or-progress-v1',JSON.stringify(progress))}catch{if(!storageFailed){storageFailed=true;toast('Browser storage is unavailable. You can practice, but your progress cannot be saved.')}}}
function saveQuiz(){try{if(quiz)localStorage.setItem('or-quiz-v1',JSON.stringify({...quiz,questions:quiz.questions.map(q=>({...q,evidence:q.evidence?.map(e=>({page:e.page,keys:e.keys}))})),sourceName:source?.name||null}));else localStorage.removeItem('or-quiz-v1')}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').className='show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',4800)}
function modal(html){$('#modal').innerHTML=`<button class="close" data-action="close-modal" aria-label="Close">×</button>${html}`;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
const chapter=n=>chapters.find(c=>c.id===n);
const chapterBank=n=>bank.filter(q=>q.chapter===n);
const groupNames=['Structure and foundations','Functional groups and reactions','Carbonyls and synthesis','Bioorganic chemistry'];
function nav(){return `<aside class="sidebar" id="sidebar"><a href="#" class="brand" data-action="home"><div class="brandmark">${icon('hex',39)}</div><div><strong>Organic Recall</strong><small>STRUCTURE INTO MEMORY</small></div></a><div class="navlabel">MY STUDY SPACE</div><a class="exam-entry" href="./review.html">Exam Studio ↗</a><nav class="nav" aria-label="Main navigation"><button data-nav="home" class="${view==='home'?'active':''}">${icon('grid')}Chapter practice<span class="badge">26</span></button><button data-nav="wrong" class="${view==='wrong'?'active':''}">${icon('review')}Review collection${progress.wrong.length?`<span class="badge">${progress.wrong.length}</span>`:''}</button><button data-nav="history" class="${view==='history'?'active':''}">${icon('clock')}Practice history</button><button data-nav="syllabus" class="${view==='syllabus'?'active':''}">${icon('book')}Textbook index</button></nav><div class="navlabel">STUDY TOOLS</div><nav class="nav"><button data-action="upload">${icon('upload')}Add lecture PDF</button><button data-action="linkbook">${icon('file')}${bookURL?'Textbook linked':'Link textbook'}</button></nav><div class="sidebook"><div class="book-cover">VOLLHARDT<br> SCHORE<span>Organic<br> Chemistry</span>6th Edition</div><strong>YOUR TEXTBOOK</strong><p>Structure and Function<br> 6th edition · 26 chapters</p></div><div class="sidefoot"><span class="statusdot"></span>Small steps. Stronger recall.</div></aside>`}
function shell(body){const labels={home:'Chapter practice',wrong:'Review collection',history:'Practice history',syllabus:'Textbook index',quiz:'Recall quiz',result:'Quiz results'};$('#app').innerHTML=`<div class="shell">${nav()}<div class="content"><header class="topbar"><div class="crumb"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>Study space <b>/　${labels[view]}</b></div><div class="topactions"><button class="topbutton" data-action="about">${icon('leaf',15)} How it works</button><span class="subtle">A little practice, every day</span><span class="avatar">C</span></div></header><main class="page" id="main" tabindex="-1">${chapterSwitcher()}${body}</main></div></div>`;bindDrop()}
function art(){return `<div class="hero-art"><svg viewBox="0 0 260 175" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="139" cy="82" r="71" stroke="#e1e8d9" stroke-dasharray="2 5"/><path d="m49 88 35-20 35 20v40l-35 20-35-20V88Zm8 5 27-16 27 16v30l-27 16-27-16V93Z" stroke="#a5b395" stroke-width="1.2"/><path d="m119 88 37-21m0 0V30m5 38V30m-5 37 33 19" stroke="#728e64" stroke-width="1.6"/><text x="150" y="23" fill="#728e64" font-size="17" font-family="Georgia">O</text><text x="189" y="96" fill="#728e64" font-size="17" font-family="Georgia">OH</text><circle cx="33" cy="47" r="3" fill="#d5e1c6"/><circle cx="219" cy="122" r="5" fill="#e3eacb"/><path d="M220 35v12m-6-6h12M34 134v8m-4-4h8" stroke="#b7c7a8"/></svg><span class="hero-note">a little practice, a stronger bond.</span></div>`}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-icon">${icon('book',20)}</div><div><div class="statlabel">Textbook chapters</div><span class="statnum">26</span><span class="statdesc"> chapters</span></div></div><div class="stat"><div class="stat-icon">${icon('check',20)}</div><div><div class="statlabel">Questions completed</div><span class="statnum">${progress.answered}</span><span class="statdesc"> questions</span></div></div><div class="stat"><div class="stat-icon">${icon('leaf',20)}</div><div><div class="statlabel">Overall accuracy</div><span class="statnum">${progress.answered?Math.round(progress.correct/progress.answered*100)+'%':'—'}</span><span class="statdesc">　${progress.answered?' / Keep growing':'/ Start with one'}</span></div></div></div>`}
function home(){view='home';render()}
function chapterSwitcher(){return `<section class="chapter-switcher" aria-label="Chapter selection"><div class="chapter-control"><label for="chapter-picker">Choose chapter</label><select id="chapter-picker" aria-label="Choose chapter">${chapters.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${String(c.id).padStart(2,'0')} · ${esc(c.title)}</option>`).join('')}</select></div><div class="chapter-actions">${view==='home'?'<button class="primary" data-action="start">Start recall quiz</button>':''}${selected===19?'<a class="secondary studio-link" href="./review.html">Chapter 19 · Visual practice ↗</a>':''}</div></section>`}
function chooseChapter(id){if(!chapter(id))return;selected=id;group='all';query='';view='home';const url=new URL(location.href);url.searchParams.set('chapter',id);history.replaceState(null,'',url);render()}

function chapterCards(){const items=chapters.filter(c=>(group==='all'||c.group===+group)&&(!query||`${c.id} ${c.title} ${c.sections.map(s=>s.title).join(' ')}`.toLowerCase().includes(query.toLowerCase())));return items.length?items.map(c=>`<button class="chapter ${selected===c.id?'selected':''}" data-chapter="${c.id}" aria-pressed="${selected===c.id}"><div class="chaptertop"><span class="chapter-num">CHAPTER ${String(c.id).padStart(2,'0')}</span>${c.id===19?'<span class="pill">Lecture example</span>':progress.seen.some(id=>id.startsWith('c'+c.id+'-'))?'<span class="pill">Practiced</span>':''}</div><h3>${esc(c.title)}</h3><div class="eng">${esc(c.sections[0]?.title||'Organic Chemistry')}</div><div class="chapterfoot"><span>${chapterBank(c.id).length} questions · pp. ${c.start}–${c.end}</span><span class="go">${selected===c.id?'Selected ✓':'Choose chapter ↗'}</span></div></button>`).join(''):'<div class="empty">No matching chapters found</div>'}
function available(){return selectQuestions(bank,{chapter:selected,count:100,types,pages:source?.chapter===selected?source.pages:[]})}
function rightPanel(){const c=chapter(selected);const av=available();return `<div class="panel"><div class="panelbody"><div class="paneltitle">${icon('upload')}Focus on your lecture</div><p class="paneldesc">Add your lecture slides as a PDF. Match their topics<br> to a short quiz from the textbook question bank.</p><button class="upload" id="drop" data-action="upload" ${uploading?'disabled':''}>${icon('upload',25)}<strong>${uploading?'Reading your PDF…':'Click or drop a lecture PDF'}</strong><span>Multiple PDFs · Up to 50 MB each</span></button>${uploadMessage?`<div class="busybox" role="status">${esc(uploadMessage)}</div>`:''}${source?`<div class="sourcecard"><button class="removefile" data-action="clear-source" aria-label="Remove lecture scope">×</button><strong>${source.example?'Example · ':''}${esc(source.name)}</strong><p>${source.totalPages} pages · Chapter ${source.chapter} · ${av.length} matching questions${source.example?' · reviewed topics':''}</p>${source.example?'<p>This example uses reviewed topic tags. Add the original PDF for page-level matches.</p>':''}</div>`:`<div class="orline">or try a lecture example</div>${examples.map(e=>`<button class="example" data-example="${e.id}">${icon('file',16)}<span>${esc(e.name)}<small>Chapter 19 · ${e.pages}-page lecture scope</small></span><span class="arrow">↗</span></button>`).join('')}`}</div></div><div class="panel"><div class="panelbody"><div class="paneltitle">${icon('settings')}Make it your practice</div><div class="scopeinfo"><strong>Chapter ${selected} · ${esc(c.title)}</strong><br> ${source&&source.chapter===selected?'Lecture-matched scope':'Full chapter bank'} · ${av.length} questions available${source&&source.chapter!==selected?'<br> Your lecture belongs to another chapter. Using the full chapter bank.':''}</div><div class="field"><div class="field-label">Questions <span>About ${count}–${count+3} min</span></div><div class="segmented" role="group" aria-label="Choose question count">${[5,8,12].map(n=>`<button class="${count===n?'active':''}" data-count="${n}" aria-pressed="${count===n}">${n} Qs</button>`).join('')}</div></div><div class="field"><div class="field-label">What to recall</div><div class="checks">${TYPES.map(t=>`<label class="chipcheck"><input type="checkbox" data-type="${t}" ${types.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><div class="field"><label class="chipcheck" style="display:inline-flex"><input type="checkbox" id="recall-toggle" ${recall?'checked':''}>Recall before revealing choices</label></div>${av.length<count?`<p class="scopeinfo">This scope contains ${av.length} questions. You will practice all of them, without repeats.</p>`:''}<div class="field"><button class="primary wide" data-action="start" ${!av.length||uploading?'disabled':''}>Start recall quiz ${icon('arrow',16)}</button></div><p class="panelnote">Simple questions · Clear explanations · No API key</p></div></div><div class="tip"><h3>${icon('leaf',15)} Give memory a moment</h3><p>Picture the product or recall the key steps,<br> then look at the choices. Take recall one step beyond recognition.</p></div>`}
function render(){if(!bank)return;if(view==='quiz')return renderQuiz();if(view==='result')return renderResult();if(view==='wrong')return renderWrong();if(view==='history')return renderHistory();if(view==='syllabus')return renderSyllabus();shell(`<section class="hero"><div><span class="eyebrow">YOUR ORGANIC CHEMISTRY COMPANION</span><h1>Make reactions stick.</h1><p>Start with a familiar chapter. Bring the essentials back to mind.<br>  Products, reagents, mechanisms, and synthesis. A little at a time.</p></div>${art()}</section>${stats()}<div class="workspace"><section class="maincol"><div class="sectionhead"><h2>Choose a chapter</h2><div class="searchwrap">${icon('search',14)}<input class="search" id="search" aria-label="Search chapters or topics" placeholder="Search chapters or topics" value="${esc(query)}"></div></div><div class="tabs" role="group" aria-label="Chapter groups"><button class="tab ${group==='all'?'active':''}" data-group="all">All chapters</button>${['Foundations 01–07','Reactions 08–16','Carbonyls 17–23','Bioorganic 24–26'].map((x,i)=>`<button class="tab ${group===String(i)?'active':''}" data-group="${i}">${x}</button>`).join('')}</div><div class="chapters" id="chapters">${chapterCards()}</div><div class="bookline"><span>Based on Vollhardt & Schore · Organic Chemistry, 6th ed.</span><span>${bank.length} original questions · Inspired by chapter-end Problems</span></div></section><aside class="rightcol" aria-label="Lecture and quiz settings">${rightPanel()}</aside></div>`)}
function start(ids=null){const questions=selectQuestions(bank,{chapter:selected,count:ids?Math.min(ids.length,12):count,types:ids?TYPES:types,pages:ids?[]:source?.chapter===selected?source.pages:[],ids});if(!questions.length)return toast('No questions match this scope. Adjust the chapter or question types.');quiz={id:crypto.randomUUID(),chapter:selected,questions,index:0,answers:Array(questions.length).fill(null),confirmed:Array(questions.length).fill(false),flags:[],reveal:!recall,recall,started:new Date().toISOString(),finished:false,sourceName:source?.chapter===selected?source.name:null};view='quiz';saveQuiz();render();scrollTo({top:0,behavior:'smooth'})}
function renderQuiz(){const q=quiz.questions[quiz.index],i=quiz.index,done=quiz.confirmed[i],choice=quiz.answers[i];shell(`<div class="quizpage"><div class="quiztop"><button class="secondary" data-action="leave-quiz">← Back to chapters</button><span>Chapter ${quiz.chapter} · ${esc(chapter(quiz.chapter).title)}</span><span>${i+1} / ${quiz.questions.length}</span></div><div class="progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${quiz.questions.length}" aria-valuenow="${quiz.confirmed.filter(Boolean).length}"><div style="width:${quiz.confirmed.filter(Boolean).length/quiz.questions.length*100}%"></div></div><article class="qcard flash"><div class="qmeta"><span class="eyebrow">RECALL ${String(i+1).padStart(2,'0')}</span><span class="qtag">${q.type}</span><span>${esc(q.topic)}</span></div><h2>${esc(q.prompt)}</h2>${quiz.reveal||done?`<div class="options">${q.options.map((o,j)=>`<button class="option ${choice===j?'chosen':''} ${done&&j===q.answer?'correct':''} ${done&&choice===j&&j!==q.answer?'incorrect':''}" data-option="${j}" ${done?'disabled':''} aria-pressed="${choice===j}"><span class="letter">${'ABCD'[j]}</span><span>${esc(o)}</span>${done&&j===q.answer?icon('check',17):''}</button>`).join('')}</div>`:'<div class="recall-prompt"><p>Say the answer aloud, or sketch the reaction on paper. Then reveal the choices.</p><button class="secondary" data-action="reveal">Reveal choices</button></div>'}${done?`<section class="explanation" aria-live="polite"><h3>${choice===q.answer?'✓ Well recalled':'One more thing to remember'} · Correct answer ${'ABCD'[q.answer]}</h3><p>${esc(q.explanation)}</p>${sourceLinks(q)}</section>`:''}<div class="qcontrols"><label class="chipcheck"><input type="checkbox" data-flag ${quiz.flags.includes(q.id)?'checked':''}>Not quite sure — save for review</label>${done?`<button class="primary" data-action="next">${i===quiz.questions.length-1?'View results':'Next question'} ${icon('arrow',16)}</button>`:`<button class="primary" data-action="confirm" ${choice===null?'disabled':''}>Check answer ${icon('check',16)}</button>`}</div></article><p class="quiz-note">${quiz.sourceName?`Scope: ${esc(quiz.sourceName)}`:'Original textbook-based recall questions'} · Understand, then remember</p></div>`)}
function sourceLinks(q){return `<div class="sources"><span>Sources</span><span>Textbook §${esc(q.section)}</span>${q.pages.map(p=>`<button class="source-link" data-bookpage="${p}">PDF p. ${p}</button>`).join('')}${q.evidence?.length&&!source?.example?q.evidence.map(e=>`<button class="source-link" data-coursepage="${e.page}">Lecture p. ${e.page} · ${esc(e.keys[0])}</button>`).join(''):''}</div>`}
function confirm(){const i=quiz.index;if(!Number.isInteger(quiz.answers[i])||quiz.confirmed[i])return;quiz.confirmed[i]=true;saveQuiz();render()}
function finish(){if(quiz.finished){view='result';render();return}quiz.finished=true;const result=grade(quiz.questions,quiz.answers),right=result.filter(r=>r.correct).length;for(const r of result){if(!r.correct||quiz.flags.includes(r.id)){if(!progress.wrong.includes(r.id))progress.wrong.push(r.id)}else progress.wrong=progress.wrong.filter(id=>id!==r.id);if(!progress.seen.includes(r.id))progress.seen.push(r.id)}progress.answered+=result.length;progress.correct+=right;progress.history.unshift({id:quiz.id,chapter:quiz.chapter,date:new Date().toISOString(),correct:right,total:result.length,minutes:Math.max(1,Math.round((Date.now()-new Date(quiz.started))/60000)),questions:quiz.questions.map(q=>q.id)});progress.history=progress.history.slice(0,200);save();saveQuiz();view='result';render();scrollTo({top:0,behavior:'smooth'})}
function reviewCard(q,choice=null,showChoice=false){return `<details class="reviewcard"><summary><span class="${showChoice?(choice===q.answer?'good':'bad'):''}">${showChoice?(choice===q.answer?'✓':'↺'):icon('review',15)}</span><h3>${esc(q.prompt)}</h3></summary><div class="reviewbody">${showChoice?`<p>Your answer: ${choice===null?'Not answered':esc(q.options[choice])}</p>`:''}<p><strong>Correct answer: ${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p>${sourceLinks(q)}${!showChoice?`<div class="footer-actions"><button class="textbtn" data-remove-wrong="${q.id}">Got it — remove from review</button></div>`:''}</div></details>`}
function renderResult(){const right=grade(quiz.questions,quiz.answers).filter(r=>r.correct).length;shell(`<div class="quizpage"><section class="scorehero"><span class="eyebrow">A LITTLE BETTER, EVERY TIME</span><div class="scorecircle">${right}<span style="font:12px var(--sans);margin-top:-28px">/ ${quiz.questions.length}</span></div><h1>${right===quiz.questions.length?'That is a strong recall.':'Every recall makes it stronger.'}</h1><p>Chapter ${quiz.chapter} · ${Math.round(right/quiz.questions.length*100)}% correct · Missed and flagged questions are saved for review</p><div class="resultactions"><button class="primary" data-action="retry-wrong">Retry missed & flagged ${icon('arrow',15)}</button><button class="secondary" data-action="home">Back to chapters</button><button class="secondary" data-action="export-quiz">Export quiz & answers</button></div></section><div class="sectionhead"><h2>Revisit the essentials</h2><span class="subtle">Open a question to see its explanation</span></div>${quiz.questions.map((q,i)=>reviewCard(q,quiz.answers[i],true)).join('')}</div>`)}
function renderWrong(){const list=progress.wrong.map(id=>bank.find(q=>q.id===id)).filter(Boolean),cs=[...new Set(list.map(q=>q.chapter))];shell(`<section class="hero"><div><span class="eyebrow">MAKE THE UNFAMILIAR FAMILIAR</span><h1>Make the unfamiliar familiar.</h1><p>Keep the questions you missed, and the ones you are not quite sure about.<br> Answer correctly to clear a question, or flag it to keep reviewing.</p></div>${art()}</section>${list.length?`<div class="sectionhead"><h2>${list.length} questions to revisit</h2><button class="secondary" data-action="export-wrong">Export review questions</button></div><div class="tabs">${cs.map(n=>`<button class="tab active" data-retrychapter="${n}">Chapter ${n} · Retry ${list.filter(q=>q.chapter===n).length} questions →</button>`).join('')}</div>${list.map(q=>reviewCard(q)).join('')}`:`<div class="empty"><h2>A clean page, for now.</h2><p>Complete a quiz to collect missed and flagged questions here.</p><button class="primary" style="margin:auto" data-action="home">Choose your first chapter</button></div>`}`)}
function renderHistory(){shell(`<section class="hero"><div><span class="eyebrow">YOUR SMALL STEPS, COLLECTED</span><h1>Every small step counts.</h1><p>Your practice on this browser, saved on this device.</p></div>${art()}</section>${stats()}<div class="sectionhead"><h2>Practice history</h2><button class="secondary" data-action="export-progress">Back up progress</button></div>${progress.history.length?progress.history.map(h=>`<div class="historyrow"><div><strong>Chapter ${h.chapter} · ${esc(chapter(h.chapter)?.title||'')}</strong><small>${h.total} questions · About ${h.minutes} min</small></div><time>${new Date(h.date).toLocaleString('en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</time><span class="subtle">${h.correct}/${h.total} correct</span><span class="num">${Math.round(h.correct/h.total*100)}%</span></div>`).join(''):'<div class="empty">Your first completed quiz will appear here.</div>'}<div class="footer-actions"><button class="textbtn" data-action="import-progress">Restore a backup</button><button class="textbtn" data-action="clear-progress">Clear local learning data</button></div>`)}
function renderSyllabus(){shell(`<section class="hero"><div><span class="eyebrow">STRUCTURE AND FUNCTION · SIXTH EDITION</span><h1>Build knowledge, chapter by chapter.</h1><p>The original 26-chapter structure, with a section-by-section index.<br> References use PDF pages. Link your textbook to open any source page.</p></div>${art()}</section><div class="sectionhead"><h2>Chapter and section index</h2><button class="secondary" data-action="linkbook">${icon('book')} ${bookURL?'Relink textbook':'Link textbook PDF'}</button></div>${chapters.map(c=>`<details class="reviewcard" ${c.id===selected?'open':''}><summary><h3><span class="chapter-num">${String(c.id).padStart(2,'0')}　</span>${esc(c.title)}</h3><span class="subtle" style="margin-left:auto">PDF ${c.start}–${c.end}</span></summary><ul class="sectionlist">${c.sections.map(s=>`<li><div>§${s.id}　${esc(s.title)}</div><button class="source-link" data-bookpage="${s.page}">p. ${s.page} ↗</button></li>`).join('')}${c.problems?`<li><strong>Problems · End of chapter</strong><button class="source-link" data-bookpage="${c.problems}">p. ${c.problems} ↗</button></li>`:''}</ul><button class="primary" data-practicechapter="${c.id}">Practice this chapter ${icon('arrow',15)}</button></details>`).join('')}`)}
async function pdfLib(){if(!pdfLib.promise)pdfLib.promise=import('./vendor/pdf.mjs').then(p=>{p.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';return p});return pdfLib.promise}
async function parseFile(file,index,total){if(file.size>50*1024*1024)throw Error(`${file.name} exceeds 50 MB. Please split the lecture PDF first.`);if(!/\.pdf$/i.test(file.name))throw Error('Please choose a PDF file.');const bytes=new Uint8Array(await file.arrayBuffer());if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw Error(`${file.name} is not a valid PDF.`);const lib=await pdfLib();const task=lib.getDocument({data:bytes,cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:'./vendor/wasm/',isEvalSupported:false});let doc;try{doc=await task.promise;if(doc.numPages>250)throw Error('Lecture PDFs are limited to 250 pages each. Split larger files, or use Link textbook for the full book.');const pages=[];for(let n=1;n<=doc.numPages;n++){if(n===1||n%5===0){uploadMessage=`File ${index}/${total} · Reading page ${n}/${doc.numPages}`;if(view==='home')render()}const page=await doc.getPage(n);const content=await page.getTextContent();pages.push({page:n,text:content.items.map(x=>x.str||'').join(' ')})}const chars=pages.reduce((s,p)=>s+p.text.replace(/\s/g,'').length,0);if(chars<Math.max(100,doc.numPages*5))throw Error(`${file.name} contains too little readable text. It may be scanned or image-based. Apply OCR before adding it, or choose a chapter to practice directly.`);return {name:file.name,pages,totalPages:doc.numPages,file,readablePages:pages.filter(p=>p.text.replace(/\s/g,'').length>=15).length}}catch(e){if(e.name==='PasswordException')throw Error('This PDF is password-protected. Please add an unlocked copy.');throw e}finally{await task.destroy()}}
async function upload(files){if(uploading)return;if(!files.length)return;uploading=true;uploadMessage='Preparing to read your PDF…';view='home';render();const docs=[],errors=[];for(let i=0;i<files.length;i++){try{docs.push(await parseFile(files[i],i+1,files.length))}catch(e){errors.push(e.message||'Could not read the file')}}uploading=false;uploadMessage='';if(!docs.length){render();modal(`<h2>No readable lecture content yet</h2>${errors.map(e=>`<p>${esc(e)}</p>`).join('')}<div class="modal-actions"><button class="secondary" data-action="close-modal">Back to chapters</button></div>`);return}const pages=[];let offset=0;for(const doc of docs){doc.offset=offset;for(const p of doc.pages)pages.push({...p,page:p.page+offset});offset+=doc.totalPages}const candidates=detectChapters(pages,chapters,bank,docs.map(d=>d.name).join(' '));draftSelection={docs,pages,totalPages:offset,candidates,errors};const best=candidates[0]?.id||selected;const matched=bank.filter(q=>q.chapter===best&&matches(q,pages).length).length;render();modal(`<h2>Confirm your lecture scope</h2><p>Read ${docs.length} PDF(s), ${offset} pages. ${candidates.length?'The suggested chapter is based on headings and topic keywords.':'There is not enough evidence to identify the chapter. Please select it below.'}</p>${docs.map(d=>`<div class="sourcecard"><strong>${esc(d.name)}</strong><p>${d.totalPages} pages · ${d.readablePages} with readable text</p></div>`).join('')}<label class="field-label" style="margin-top:18px" for="detected-chapter">Confirm the chapter · lecture PDFs for the same chapter can be combined</label><select class="chapterselect" id="detected-chapter">${chapters.map(c=>`<option value="${c.id}" ${c.id===best?'selected':''}>Chapter ${c.id} · ${esc(c.title)}</option>`).join('')}</select><p id="detected-count">${matched} questions in this chapter match keywords in the PDF.</p><p>Matching uses readable text. Reactions embedded in drawings may be missed. For a multi-chapter file, practice one chapter at a time.</p>${errors.map(e=>`<div class="warn">${esc(e)}</div>`).join('')}<div class="modal-actions"><button class="primary" data-action="apply-upload">Use this scope</button><button class="secondary" data-action="cancel-upload">Cancel</button></div>`)}
function clearSource(){if(source?.docs)for(const d of source.docs)if(d.url)URL.revokeObjectURL(d.url);source=null}
function applyUpload(){const n=+$('#detected-chapter').value;clearSource();source={...draftSelection,chapter:n,name:draftSelection.docs.map(d=>d.name).join(' + ')};draftSelection=null;selected=n;group='all';query='';closeModal();home();toast('Lecture scope is ready. Choose question types and start practicing.')}
function sourcePage(n){if(!source||source.example)return toast('Examples contain topic scopes. Add the original PDF to inspect matching pages.');const doc=source.docs.find(d=>n>d.offset&&n<=d.offset+d.totalPages);if(!doc)return toast('Add the lecture PDF again to reopen its original pages.');if(!doc.url)doc.url=URL.createObjectURL(doc.file);window.open(doc.url+'#page='+(n-doc.offset),'_blank','noopener')}
async function linkBook(file){if(processingBook)return;processingBook=true;try{const bytes=new Uint8Array(await file.arrayBuffer());if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw Error('Please choose a valid textbook PDF.');const lib=await pdfLib();const task=lib.getDocument({data:bytes,isEvalSupported:false});try{const doc=await task.promise;if(doc.numPages!==1374)throw Error(`This PDF has ${doc.numPages} pages; the supplied textbook has 1,374. Choose the original sixth-edition PDF so source pages line up.`);const page=await doc.getPage(905);const text=(await page.getTextContent()).items.map(x=>x.str||'').join(' ');if(!/carboxylic/i.test(text))throw Error('The page count matches, but page 905 does not match Chapter 19. Please choose the original textbook PDF.');if(bookURL)URL.revokeObjectURL(bookURL);bookURL=URL.createObjectURL(file);bookName=file.name;closeModal();render();if(linkBook.pendingPage){window.open(bookURL+'#page='+linkBook.pendingPage,'_blank','noopener');linkBook.pendingPage=null}toast('Textbook linked. Source pages can now be opened during this visit.')}finally{await task.destroy()}}catch(e){toast(e.message||'Could not link this textbook. Please try again.')}finally{processingBook=false}}
function openBook(p){if(bookURL)return window.open(bookURL+'#page='+p,'_blank','noopener');linkBook.pendingPage=p;modal(`<h2>Open textbook PDF p. ${p}</h2><p>This question is grounded in your sixth-edition textbook. Link the original PDF to jump to the source page. The file stays in your browser.</p><p>Choose the supplied sixth-edition textbook PDF (1,374 pages). References use PDF page numbers, which differ from printed page numbers.</p><div class="modal-actions"><button class="primary" data-action="choose-book">Link textbook PDF</button><button class="secondary" data-action="close-modal">Not now</button></div>`)}
function download(name,content,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportQuestions(list,title){download(`${title}.md`,`# ${title}\n\nOriginal recall questions based on the concepts and chapter-end problem styles in Vollhardt & Schore, sixth edition.\n\n`+list.map((q,i)=>`## ${i+1}. ${q.prompt}\n\n${q.options.map((o,j)=>`${'ABCD'[j]}. ${o}`).join('\n')}\n\nAnswer: ${'ABCD'[q.answer]}\n\n${q.explanation}\n\nSource: textbook Chapter ${q.chapter}, §${q.section}, PDF pp. ${q.pages.join(', ')}.\n`).join('\n'))}
function about(){modal(`<h2>Independent organic chemistry practice</h2><p>This website runs in your browser. It does not require ChatGPT, an OpenAI account, or an API key. PDF parsing, question matching, grading, and progress storage run locally on your device.</p><p>${bank.length} original recall questions organized around the 26 chapters of Organic Chemistry: Structure and Function, sixth edition. Inspired by chapter-end Problems, they focus on products, reagents, mechanisms, and short syntheses.</p><p><strong>How lecture matching works: </strong>The browser reads PDF text, suggests a chapter, and matches its keywords to the question bank after you confirm the scope. Questions are selected from a prepared bank, rather than generated by AI. A matching page supplies keyword evidence; chemical drawings may not be read. New reactions outside the bank require additional questions.</p><p><strong>Chapter 19: </strong>36 questions checked against your two lecture PDFs (52 and 43 pages). Examples use reviewed topic tags; the original PDFs are not hosted. Chapter 7, missing a top-level bookmark, was recovered from its section headings.</p><p><strong>Your data: </strong>Lecture files and your linked textbook are processed in this browser, without uploading them to the website server. Progress is stored on this device, not synced across devices. Unfinished quizzes can be resumed after a refresh; reopen the PDFs to inspect their original pages. Export a backup from Practice history.</p><p>The textbook text and diagrams are not reproduced as a whole. This is a personal recall tool. Continue practicing full mechanisms and electron-pushing arrows on paper.</p><div class="modal-actions"><button class="primary" data-action="close-modal">Start learning</button></div>`)}
function bindDrop(){const drop=$('#drop');if(!drop)return;drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');upload([...e.dataTransfer.files])}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-action]');if(!b)return;const ds=b.dataset;const act=ds.action;if(b.tagName==='A')e.preventDefault();if(ds.nav){view=ds.nav;render();scrollTo(0,0);return}if(ds.chapter){chooseChapter(+ds.chapter);return}if(ds.group){group=ds.group;render();return}if(ds.count){count=+ds.count;render();return}if(ds.example){clearSource();const ex=examples.find(x=>x.id===+ds.example);selected=19;source={chapter:19,name:ex.name,totalPages:ex.pages,pages:[{page:1,text:ex.text}],example:true};render();toast('Reviewed lecture topics loaded.');return}if(ds.option!==undefined){if(!quiz.confirmed[quiz.index]){quiz.answers[quiz.index]=+ds.option;saveQuiz();render()}return}if(ds.bookpage){openBook(+ds.bookpage);return}if(ds.coursepage){sourcePage(+ds.coursepage);return}if(ds.removeWrong){progress.wrong=progress.wrong.filter(x=>x!==ds.removeWrong);save();render();return}if(ds.retrychapter){selected=+ds.retrychapter;start(progress.wrong.filter(id=>bank.some(q=>q.id===id&&q.chapter===selected)));return}if(ds.practicechapter){selected=+ds.practicechapter;query='';group='all';home();scrollTo(0,0);return}switch(act){case 'home':home();scrollTo(0,0);break;case 'menu':$('#sidebar').classList.toggle('open');break;case 'upload':$('#pdf-input').click();break;case 'clear-source':clearSource();render();break;case 'start':start();break;case 'confirm':confirm();break;case 'next':if(quiz.index===quiz.questions.length-1)finish();else{quiz.index++;quiz.reveal=!quiz.recall;saveQuiz();render();scrollTo({top:0,behavior:'smooth'})}break;case 'reveal':quiz.reveal=true;saveQuiz();render();break;case 'leave-quiz':home();break;case 'resume':{const saved=safeLoad(localStorage,'or-quiz-v1',null);if(saved&&saved.questions?.length){quiz=saved;view=saved.finished?'result':'quiz';render()}break}case 'discard-quiz':quiz=null;saveQuiz();closeModal();home();break;case 'retry-wrong':{const ids=quiz.questions.filter((q,i)=>quiz.answers[i]!==q.answer||quiz.flags.includes(q.id)).map(q=>q.id);if(ids.length){selected=quiz.chapter;start(ids)}else toast('You answered every question correctly. Choose a chapter for another round.');break}case 'linkbook':linkBook.pendingPage=null;$('#book-input').click();break;case 'choose-book':$('#book-input').click();break;case 'close-modal':closeModal();break;case 'apply-upload':applyUpload();break;case 'cancel-upload':draftSelection=null;closeModal();break;case 'about':about();break;case 'export-quiz':exportQuestions(quiz.questions,`Organic-Recall-Chapter-${quiz.chapter}-Quiz`);break;case 'export-wrong':exportQuestions(progress.wrong.map(id=>bank.find(q=>q.id===id)).filter(Boolean),'Organic-Recall-Review');break;case 'export-progress':download('Organic-Recall-Progress.json',JSON.stringify({version:1,progress},null,2),'application/json');break;case 'import-progress':importProgress();break;case 'clear-progress':modal('<h2>Clear learning data on this device?</h2><p>This removes practice history, review questions, and unfinished quizzes. Export a backup first if needed.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Cancel</button><button class="primary" data-action="confirm-clear">Clear data</button></div>');break;case 'confirm-clear':progress={history:[],wrong:[],seen:[],correct:0,answered:0};quiz=null;save();saveQuiz();closeModal();render();toast('Learning data on this device has been cleared.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='chapter-picker'){chooseChapter(+e.target.value);return}if(e.target.dataset.type){types=[...document.querySelectorAll('[data-type]:checked')].map(x=>x.dataset.type);render()}if(e.target.id==='recall-toggle')recall=e.target.checked;if(e.target.hasAttribute('data-flag')){const id=quiz.questions[quiz.index].id;quiz.flags=e.target.checked?[...new Set([...quiz.flags,id])]:quiz.flags.filter(x=>x!==id);saveQuiz()}if(e.target.id==='detected-chapter'){const n=+e.target.value;$('#detected-count').textContent=`${bank.filter(q=>q.chapter===n&&matches(q,draftSelection.pages).length).length} questions match keywords in this PDF.`}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#chapters').innerHTML=chapterCards()}});
$('#pdf-input').onchange=e=>{upload([...e.target.files]);e.target.value=''};
$('#book-input').onchange=e=>{const file=e.target.files[0];if(file)linkBook(file);e.target.value=''};
async function importProgress(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Backup file is too large');const data=JSON.parse(await file.text()),p=data.progress;const ids=new Set(bank.map(q=>q.id));if(data.version!==1||!p||!Array.isArray(p.history)||!Array.isArray(p.wrong)||!Array.isArray(p.seen)||!Number.isInteger(p.answered)||!Number.isInteger(p.correct)||p.correct<0||p.correct>p.answered||p.answered<0||p.history.length>200||p.history.some(h=>!chapter(h.chapter)||!Number.isInteger(h.total)||!Number.isInteger(h.correct)||h.total<1||h.correct<0||h.correct>h.total||!Number.isFinite(Date.parse(h.date))||!Number.isFinite(h.minutes)||!Array.isArray(h.questions)||h.questions.some(id=>!ids.has(id)))||p.wrong.some(x=>!ids.has(x))||p.seen.some(x=>!ids.has(x)))throw Error('Backup format or question IDs do not match');progress=p;save();render();toast('Learning progress restored.')}catch(e){toast('Could not restore: '+e.message)}};input.click()}
async function init(){try{[chapters,bank,examples]=await Promise.all(['chapters','bank','examples'].map(async x=>{const r=await fetch('./'+x+'.json');if(!r.ok)throw Error('Learning data could not be loaded');return r.json()}));const requestedChapter=Number(new URLSearchParams(location.search).get('chapter'));if(chapter(requestedChapter))selected=requestedChapter;progress.wrong=progress.wrong.filter(id=>bank.some(q=>q.id===id));render();const saved=safeLoad(localStorage,'or-quiz-v1',null);if(saved&&!saved.finished&&saved.questions?.length&&chapter(saved.chapter)&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<saved.questions.length&&saved.questions.every(q=>bank.some(x=>x.id===q.id))){toast('An unfinished quiz is available to resume.');modal(`<h2>Pick up where you left off</h2><p>Chapter ${saved.chapter} · ${saved.confirmed.filter(Boolean).length}/${saved.questions.length} questions completed. Reopen lecture files to inspect source pages.</p><div class="modal-actions"><button class="primary" data-action="resume" onclick="this.closest('dialog').close()">Resume quiz</button><button class="secondary" data-action="discard-quiz">Start fresh</button></div>`)}}catch(e){$('#app').innerHTML='<div class="empty"><h2>Learning data is temporarily unavailable</h2><p>Check your connection and reload. For local use, open the site through an HTTP server.</p></div>';console.error(e)}}
init();
